SLUTMALL_STIL = {"logga": 100, "ikoner": 100, "rad1": 100, "rubrik": 100, "cta": 100, "bredd": 778, "hojd": 0,
                 "luft_logga": 0, "luft_rad1": 0, "luft_rubrik": 0, "luft_cta": 0, "luft_ikoner": 0, "tempo": 100}
SLUTMALL_SKAK = {"small": 100, "studs": 40}
STORLEK = {"9x16": (1080, 1920), "4x5": (1080, 1350)}


def slutmall_varden(form):
    effekt = form.get("effekt") or "small"
    stil = form.get("stil") if isinstance(form.get("stil"), dict) else {}
    varden = {"mall": form.get("mall") or "alla", "text1": form.get("rad1") or "", "text2": form.get("rad2") or "",
              "effekt": effekt, **SLUTMALL_STIL, "skak": SLUTMALL_SKAK.get(effekt, 0)}
    varden.update({k: v for k, v in stil.items() if k in varden})
    return varden


def fyll_slutmallar(apps, schema_editor):
    Job = apps.get_model("engine", "SmsFilmJob")
    Output = apps.get_model("engine", "SmsFilmOutput")
    for job in Job.objects.filter(kind="slutmall", mall_id=""):
        form = job.form or {}
        fmt = form.get("format") if form.get("format") in STORLEK else "9x16"
        job.mall_id = "golfkuponger-slutmallar"
        job.varden = slutmall_varden(form)
        job.formats = [fmt]
        job.save(update_fields=["mall_id", "varden", "formats"])
        if job.output_asset_id:
            Output.objects.get_or_create(job=job, typ="video", format=fmt, variant="", defaults={
                "bredd": STORLEK[fmt][0], "hojd": STORLEK[fmt][1], "langd": job.duration_s, "asset_id": job.output_asset_id})


